    // call sites (`let source = HttpPackSource::new(...);`, unawaited) keep compiling.
    pub fn new(url: String, transport: T, runtime: RetryRuntime) -> Self {
        Self::with_retry_policy(url, transport, RetryPolicy::default(), runtime)
    }

