    // 🚫️async: no suspension point — same constructor reasoning as `new` above.
    pub fn with_retry_policy(url: String, transport: T, retry_policy: RetryPolicy, runtime: RetryRuntime) -> Self {
        let shared = Arc::new(SharedState::new());
